formulas.expression:
IF( {!get_Placement.Client_is__c} = true
 ,  {!fm_DuetoProducing}  -  IF( ISNULL( {!fm_ProducingBrkg} ) , 0 , {!fm_ProducingBrkg} )  -  IF( ISNULL( {!Loop_Settlement_Line_Item.RefReinsuranceDetail__r.ToProducingAdminFee__c} ) , 0 , {!Loop_Settlement_Line_Item.RefReinsuranceDetail__r.ToProducingAdminFee__c} )
 ,  {!fm_DuetoProducing}
)

IF( {!fm_DuetoProducing} = null || {!fm_DuetoProducing} = 0
  ,  IF( {!fm_DuetoNoteIssuer} = null || {!fm_DuetoNoteIssuer} = 0
    ,  IF( {!fm_DuetoUnderwriter} = null || {!fm_DuetoUnderwriter} = 0
      ,  IF( {!fm_DuetoPlacingTogether} = null || {!fm_DuetoPlacingTogether} = 0
        ,  {!fm_DuetoSeperateCoBroker}
        ,  {!fm_DuetoPlacingTogether}
        )
      ,  {!fm_DuetoUnderwriter}
      )
    ,  {!fm_DuetoNoteIssuer}
    )
  ,  {!fm_DuetoProducing}
  )

IF( {!fm_NoteType} = 'Debit' ,
IF( {!v_LayerCount} = {!v_QSCount} , "LOL: as per slip",
  IF( {!v_QSCount} = 0 , "LOL : " & TEXT( {!Loop_Settlement_Line_Item.RefPanel__r.Currency__c} ) & " " & {!fm_MaxLOL_Unit} & " xs " & {!fm_MinLOL_Unit} ,
    "LOL : " & TEXT( {!Loop_Settlement_Line_Item.RefPanel__r.Currency__c} ) & " " & {!fm_MaxLOL_Unit} & " xs " & {!fm_MinLOL_Unit} & " and as per slip" 
  )
)
, "LOL : " & TEXT( {!Loop_Settlement_Line_Item.RefPanel__r.Currency__c} ) & " " & {!Loop_Settlement_Line_Item.RefPanel__r.Layer_md__r.Layer_fm__c}  & " - Premium: " & {!get_Slip.DepositPrem__c}
)
